type Pick<T, K extends keyof T> = { [P in K]: T[P] }; type Omit<T, K extends keyof any> = Pick<T, Exclude<keyof T, K>>; type NonNullable<T> = T & {}; type Data = { a: string; b: number }; type Empty = Pick<Data, never>; type Nullable = Omit<Data | null, 'a'>; type EmptyIntersection = Omit<Data, keyof Data> & Omit<Data, keyof Data>; type NonemptyIntersection = Omit<Data, keyof Data> & { other: string }; type Generic<T> = Omit<T, keyof T>; type Nonempty = Omit<Data, 'a'>; type MakeRequired<Base, Key extends keyof Base> = NonNullable<Base[Key]>; type UnknownAlias = unknown; type Intrinsic = NonNullable<unknown>; type Aliased = NonNullable<UnknownAlias>;
